import pandas as pd
import pytest

from piggy_bank.etica import COL_DATA, COL_MINUS, COL_PLUS

# The *_rc.py modules are generated by `./driver.sh -b`
pytest.importorskip('piggy_bank.ui.filter_tools_rc', reason='UI not built, run ./driver.sh -b')

from piggy_bank.aggr_stats import AggrStats  # noqa: E402
from piggy_bank.filter_tools import FilterTools  # noqa: E402
from piggy_bank.qw_misc import NumericTableWidgetItem  # noqa: E402


@pytest.fixture
def df():
    return pd.DataFrame({
        COL_DATA: ['2024-03-05', '2025-07-20'],
        COL_MINUS: [-250.4, None],
        COL_PLUS: [None, 1200.9],
    })


def test_numeric_item_sorts_numerically(qtbot):
    assert NumericTableWidgetItem('9') < NumericTableWidgetItem('10')
    assert NumericTableWidgetItem('-100') < NumericTableWidgetItem('')  # empty counts as 0


def test_aggr_stats(qtbot):
    w = AggrStats('All')
    qtbot.addWidget(w)

    w.update_stats([1.0, 2.0, 3.0, 10.0])

    assert w.qgb.title() == 'All'
    assert w.ql_entries.text().strip() == '4'
    assert (w.ql_min.text(), w.ql_max.text(), w.ql_sum.text()) == ('1', '10', '16')
    assert w.ql_median.text() == '2'  # 2.5 rounded half to even
    assert w.isEnabled()


@pytest.mark.parametrize('values, colour', [([-10.0, 5.0, -1.0], '#d62728'), ([10.0, -5.0, 1.0], '#2ca02c'),
                                             ([0.0], '#2ca02c')])
def test_aggr_stats_coloured(qtbot, values, colour):
    w = AggrStats('All', coloured=True)
    qtbot.addWidget(w)

    w.update_stats(values)

    for label in (w.ql_sum, w.ql_median, w.ql_avg):
        assert colour in label.styleSheet()
    for label in (w.ql_entries, w.ql_min, w.ql_max, w.ql_std):
        assert label.styleSheet() == ''


def test_aggr_stats_coloured_mixed_signs(qtbot):
    w = AggrStats('All', coloured=True)
    qtbot.addWidget(w)

    # sum 30 >= 0, median -1 < 0, mean 7.5 >= 0
    w.update_stats([-2.0, -1.0, -1.0, 34.0])

    assert '#2ca02c' in w.ql_sum.styleSheet()
    assert '#d62728' in w.ql_median.styleSheet()
    assert '#2ca02c' in w.ql_avg.styleSheet()


def test_aggr_stats_not_coloured_by_default(qtbot):
    w = AggrStats('Out')
    qtbot.addWidget(w)

    w.update_stats([-10.0])

    assert all(label.styleSheet() == '' for label in (w.ql_sum, w.ql_median, w.ql_avg))


def test_aggr_stats_empty(qtbot):
    w = AggrStats('Out')
    qtbot.addWidget(w)

    w.update_stats([])
    assert not w.isEnabled()

    w.update_stats([], hide_if_empty=True)
    assert w.isHidden()


def test_filter_tools_defaults_from_data(qtbot, df):
    ft = FilterTools(df)
    qtbot.addWidget(ft)
    ft.setup_sliders(df)

    assert ft.qde_start.date().toString('yyyy-MM-dd') == '2024-03-05'
    assert ft.qde_end.date().toString('yyyy-MM-dd') == '2025-07-20'
    assert ft.qrs_out.value() == (-250, -250)
    assert ft.qrs_in.value() == (1200, 1200)
    assert ft.qrb_bl_all.isChecked()
    assert ft.qrb_inv_all.isChecked()


@pytest.mark.parametrize('group', ['bl', 'inv'])
def test_filter_tools_every_radio_triggers_filtering(qtbot, df, group):
    ft = FilterTools(df)
    qtbot.addWidget(ft)
    radio = {mode: getattr(ft, f'qrb_{group}_{mode}') for mode in ('all', 'force', 'veto')}

    # Going back to All must refilter too, not only Force/Veto
    for mode in ('force', 'veto', 'all'):
        with qtbot.waitSignal(ft.filters_updated, timeout=2000):
            radio[mode].click()
        assert radio[mode].isChecked()


def test_filter_tools_defaults_come_from_ui(qtbot, df):
    ft = FilterTools(df)
    qtbot.addWidget(ft)
    ft.qrb_bl_veto.click()
    ft.qrb_inv_force.click()

    ft.qpb_reset.click()

    assert ft.brg_bl.checkedButton() is ft.qrb_bl_all
    assert ft.brg_inv.checkedButton() is ft.qrb_inv_all


def test_filter_tools_button_added_to_group_is_wired(qtbot, df):
    """Wiring follows the QButtonGroup, so a radio added in Designer needs no Python change."""
    from PySide6.QtWidgets import QRadioButton
    ft = FilterTools(df)
    qtbot.addWidget(ft)
    extra = QRadioButton('Extra', ft)
    ft.brg_inv.addButton(extra)

    with qtbot.waitSignal(ft.filters_updated, timeout=2000):
        extra.click()


def test_filter_tools_groups_are_independent(qtbot, df):
    ft = FilterTools(df)
    qtbot.addWidget(ft)

    ft.qrb_bl_force.click()
    ft.qrb_inv_veto.click()

    assert ft.qrb_bl_force.isChecked() and ft.qrb_inv_veto.isChecked()


def test_filter_tools_dates_have_calendar_popup(qtbot, df):
    ft = FilterTools(df)
    qtbot.addWidget(ft)

    assert ft.qde_start.calendarPopup() and ft.qde_end.calendarPopup()


def test_filter_tools_reset_restores_defaults_and_emits(qtbot, df):
    ft = FilterTools(df)
    qtbot.addWidget(ft)
    ft.setup_sliders(df)

    ft.qle_description.setText('pizza')
    ft.qrb_bl_force.setChecked(True)
    ft.qrb_inv_veto.setChecked(True)
    ft.qchk_out.setChecked(False)

    with qtbot.waitSignal(ft.filters_updated, timeout=500):
        ft.qpb_reset.click()

    assert ft.qle_description.text() == ''
    assert ft.qrb_bl_all.isChecked()
    assert ft.qrb_inv_all.isChecked()
    assert ft.qchk_out.isChecked() and ft.qrs_out.isEnabled()


def test_filter_tools_text_is_debounced(qtbot, df):
    ft = FilterTools(df)
    qtbot.addWidget(ft)

    with qtbot.assertNotEmitted(ft.filters_updated, wait=200):
        ft.qle_description.setText('a')
    with qtbot.waitSignal(ft.filters_updated, timeout=2000):
        pass
